import{_ as s,C as n,o as e,c as d,j as i,a as r,E as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const R=JSON.parse(`{"title":"6-dars (Mentor). Balsamiq va Axure RP: asosiy UI komponentlar va dastlabki interfeys sxemalari","description":"","frontmatter":{"title":"6-dars (Mentor). Balsamiq va Axure RP: asosiy UI komponentlar va dastlabki interfeys sxemalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":2,"link":"/mentor/9-sinf/hafta-02/"},"g":6,"title":"Balsamiq va Axure RP: asosiy UI komponentlar va dastlabki interfeys sxemalari","lead":"Birgina g'oya bor, lekin uni millionlab foydalanuvchilar tushunadigan interfeysga qanday aylantirish mumkin? Ushbu darsda professional Axure RP va Balsamiq vositalarida murakkab bloklar, sahifalar navigatsiyasi, kulranglar ierarxiyasi va wireframelarni Figmaga tayyorlashni o'rganamiz.","slide":"/slaydlar/9-sinf/hafta-02/dars-3.html","test":"/slaydlar/9-sinf/hafta-02/dars-3-test.html","student_link":"/9-sinf/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/9-sinf/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/9-sinf/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Wireframe tushunchasi va Balsamiq dasturiga kirish","link":"/mentor/9-sinf/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf/hafta-02/dars-3.md","filePath":"mentor/9-sinf/hafta-02/dars-3.md"}`),h={name:"mentor/9-sinf/hafta-02/dars-3.md"},m={class:"blk"},u={id:"_1-dars-rejasi",tabindex:"-1"},g={class:"blk"},k={id:"_2-konspekt",tabindex:"-1"},f={class:"blk"},b={id:"_3-amaliy-topshiriqlar",tabindex:"-1"},q={class:"blk"},y={id:"_4-tezkor-nazorat-5-daqiqa",tabindex:"-1"},p={class:"blk"},c={id:"_5-xulosa-va-keyingi-darsga-ko-prik",tabindex:"-1"};function v(_,a,x,P,z,A){const t=n("Icon");return e(),d("div",null,[a[15]||(a[15]=i("p",null,[i("strong",null,"Hafta:"),r(" 2 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" nazariya + amaliyot · "),i("strong",null,"I-bob"),r(", 6-dars")],-1)),i("div",m,[i("h2",u,[l(t,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o('<p><strong>Maqsad:</strong> o&#39;quvchi Balsamiq va Axure RP dasturlarining imkoniyatlarini taqqoslay oladi, Axure RP ning asosiy ishchi panellari bilan tanishadi, sahifalarni to&#39;g&#39;ri nomlashni, to&#39;rtburchaklar (Rectangle) va matnlar yordamida interfeys bloklarini tuzishni hamda tayyor wireframe&#39;ni PNG/SVG formatida eksport qilib, Figmaga o&#39;tkazishga tayyorlashni o&#39;rganadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Axure RP va Balsamiq vositalarining vazifalari va farqlarini ajrata oladi.</li><li>Axure RP ish maydonida (Canvas, Pages, Widgets Library, Interactions) yo&#39;nalish oladi.</li><li>Sahifalarni mantiqiy nomlash (<code>Home_books</code>, <code>Book_details</code>) tamoyillarini biladi.</li><li>Kulrang tuslar palitrasi (Grayscale) yordamida elementlar ierarxiyasini vizual ajratadi.</li><li>1 ta to&#39;liq veb yoki mobil ilova wireframe sxemasini tuzadi va uni rasm (PNG) ko&#39;rinishida saqlaydi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10</td><td>Takrorlash</td><td>5-dars (Wireframe tushunchasi, Low-fi, Balsamiq asoslari)</td></tr><tr><td>10–30</td><td>Yangi mavzu 1</td><td>Axure RP dasturi: professional prototiplash va Balsamiq bilan taqqoslash</td></tr><tr><td>30–40</td><td>Yangi mavzu 2</td><td>Axure RP interfeysi: Pages, Default Widgets, Rectangle va Matn</td></tr><tr><td>40–45</td><td>Tanaffus</td><td></td></tr><tr><td>45–55</td><td>Yangi mavzu 3</td><td>Kulranglar ierarxiyasi, eksport (PNG/SVG) va Figmaga tayyorlash</td></tr><tr><td>55–75</td><td>Amaliyot</td><td>&quot;Home_books&quot; sahifasi to&#39;liq wireframe sxemasini yasash</td></tr><tr><td>75–80</td><td>Tezkor nazorat va xulosa</td><td>5 ta savol, 2-hafta yakuni</td></tr></tbody></table><p><strong>Vositalar:</strong> Axure RP (bepul trial) yoki Balsamiq / Figma (oq-qora rejimda).</p><hr>',6))]),i("div",g,[i("h2",k,[l(t,{name:"file-text"}),a[3]||(a[3]=r(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=o('<h3 id="_2-1-takrorlash-10-daqiqa" tabindex="-1">2.1. Takrorlash (10 daqiqa) <a class="header-anchor" href="#_2-1-takrorlash-10-daqiqa" aria-label="Permalink to &quot;2.1. Takrorlash (10 daqiqa)&quot;">​</a></h3><ul><li>Low-fidelity wireframe nima uchun kerak?</li><li>Balsamiq&#39;da &quot;X&quot; bilan chizilgan to&#39;rtburchak nimani bildiradi?</li></ul><h3 id="_2-2-axure-rp-nima-va-u-balsamiqdan-nimasi-bilan-farq-qiladi" tabindex="-1">2.2. Axure RP nima va u Balsamiqdan nimasi bilan farq qiladi? <a class="header-anchor" href="#_2-2-axure-rp-nima-va-u-balsamiqdan-nimasi-bilan-farq-qiladi" aria-label="Permalink to &quot;2.2. Axure RP nima va u Balsamiqdan nimasi bilan farq qiladi?&quot;">​</a></h3><p><strong>Axure RP</strong> — UI/UX dizayn sohasida murakkab interfeyslar, wireframelar va yuqori darajada interaktiv prototiplar yaratish uchun mo&#39;ljallangan qudratli professional dasturdir.</p><table tabindex="0"><thead><tr><th>Xususiyat</th><th>Balsamiq</th><th>Axure RP</th></tr></thead><tbody><tr><td><strong>Asosiy uslub</strong></td><td>Qalamaki, daftardagi eskiz (sketch)</td><td>Geometrik toza, professional karkas</td></tr><tr><td><strong>Maqsad</strong></td><td>Dastlabki tezkor g&#39;oyalar (5-10 daqiqa)</td><td>To&#39;liq va batafsil interfeys sxemalari</td></tr><tr><td><strong>Mantiq va shartlar</strong></td><td>Faqat oddiy havolalar</td><td>Murakkab o&#39;zgaruvchilar, formulalar, shartli o&#39;tishlar</td></tr><tr><td><strong>Murakkablik</strong></td><td>Juda sodda, o&#39;rganish 1 kun</td><td>Professional, ko&#39;proq vositalarga ega</td></tr></tbody></table><h3 id="_2-3-axure-rp-ning-asosiy-panellari" tabindex="-1">2.3. Axure RP ning asosiy panellari <a class="header-anchor" href="#_2-3-axure-rp-ning-asosiy-panellari" aria-label="Permalink to &quot;2.3. Axure RP ning asosiy panellari&quot;">​</a></h3><ol><li><strong>Pages (Sahifalar paneli):</strong> Loyihaning barcha sahifalari daraxtsimon (tree structure) ko&#39;rinishida saqlanadi. Sahifalarni tartibli nomlash shart: masalan, <code>Home_books</code>, <code>Search_results</code>, <code>Profile</code>.</li><li><strong>Canvas (Ish maydoni):</strong> Markaziy hudud, pikselli setka (grid) bilan jihozlangan.</li><li><strong>Libraries / Default Widgets (Komponentlar kutubxonasi):</strong><ul><li><em>Rectangle (To&#39;rtburchak):</em> Har qanday banner, karta, sarlavha qutisi uchun asosiy g&#39;isht.</li><li><em>Text (Matn):</em> Sarlavha (Heading) va tavsiflar.</li><li><em>Droplist, Checkbox, Radio:</em> Formalar uchun vidjetlar.</li></ul></li><li><strong>Interactions paneli:</strong> Tanlangan element bosilganda qayerga o&#39;tish, animatsiya va dinamik holatlarni boshqaradi.</li></ol><h3 id="_2-4-kulranglar-ierarxiyasi-grayscale-hierarchy" tabindex="-1">2.4. Kulranglar ierarxiyasi (Grayscale Hierarchy) <a class="header-anchor" href="#_2-4-kulranglar-ierarxiyasi-grayscale-hierarchy" aria-label="Permalink to &quot;2.4. Kulranglar ierarxiyasi (Grayscale Hierarchy)&quot;">​</a></h3><p>Wireframe&#39;da rang ishlatilmaydi, ammo bu barcha bloklar bir xil bo&#39;ladi degani emas! Dizaynerlar bir xil rang o&#39;rniga <strong>kulrangning 3–4 xil tusini</strong> ishlatishadi:</p><ul><li><strong>To&#39;q kulrang (#334155):</strong> Asosiy sarlavhalar va eng muhim tugmalar uchun.</li><li><strong>O&#39;rta kulrang (#94a3b8):</strong> Ikkilamchi matnlar va chegaralar (border) uchun.</li><li><strong>Och kulrang (#f1f5f9):</strong> Fon bloklari, bannerlar va kartalar asosi uchun.</li><li><strong>Oq (#ffffff):</strong> Sahifaning asosiy foni yoki kartalar ichi uchun.</li></ul><p>Bu usul ko&#39;zga qaysi element eng muhim ekanini rangsiz ham bir qarashda ko&#39;rsatib beradi.</p><h3 id="_2-5-eksport-va-figmaga-ko-chirish" tabindex="-1">2.5. Eksport va Figmaga ko&#39;chirish <a class="header-anchor" href="#_2-5-eksport-va-figmaga-ko-chirish" aria-label="Permalink to &quot;2.5. Eksport va Figmaga ko&#39;chirish&quot;">​</a></h3><p>Wireframe tayyor bo&#39;lgach:</p><ol><li><code>File → Export to Image</code> (PNG yoki SVG formatida).</li><li>Keyingi bosqichda ushbu PNG rasm <strong>Figma</strong> dasturiga yuklanadi (drag-and-drop orqali).</li><li>Wireframe rasm sifatida fonga qulflanadi (Lock) va uning ustiga haqiqiy ranglar, shriftlar hamda piktogrammalar chizilib, chiroyli <strong>UI dizayn</strong> shakllantiriladi!</li></ol><hr>',15))]),i("div",f,[i("h2",b,[l(t,{name:"file-text"}),a[6]||(a[6]=r(" 3. Amaliy topshiriqlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-home-books-veb-sahifasi-wireframe-i" tabindex="-1">1-topshiriq. &quot;Home_books&quot; veb-sahifasi wireframe&#39;i <a class="header-anchor" href="#_1-topshiriq-home-books-veb-sahifasi-wireframe-i" aria-label="Permalink to &quot;1-topshiriq. &quot;Home_books&quot; veb-sahifasi wireframe&#39;i&quot;">​</a></h3><p>Axure RP (yoki Balsamiq/Figma)da quyidagi bloklardan iborat veb-sahifa maketini tuzing:</p><ol><li>Sahifa nomi: <code>Home_books</code>;</li><li>Yuqori qism (Header): Logo uchun to&#39;rtburchak va 4 ta matnli menyu havolasi;</li><li>Katta banner (Rectangle): Sarlavha matni va o&#39;ng tomonida kitob rasmi o&#39;rni ([X]);</li><li>&quot;Tavsiya etilgan kitoblar&quot; bo&#39;limi: 3 ta bir xil to&#39;rtburchak kartalar (Grid).</li></ol><p><strong>Yechim:</strong></p><ul><li>Header balandligi 70px, och kulrang fon;</li><li>Banner balandligi 250px, ichida qalin sarlavha va &quot;Batafsil&quot; tugmasi;</li><li>3 ta karta orasidagi masofa (gap) 24px teng taqsimlangan.</li></ul><h3 id="_2-topshiriq-axure-rp-da-interaktiv-bog-lanish-link" tabindex="-1">2-topshiriq. Axure RP da interaktiv bog&#39;lanish (Link) <a class="header-anchor" href="#_2-topshiriq-axure-rp-da-interaktiv-bog-lanish-link" aria-label="Permalink to &quot;2-topshiriq. Axure RP da interaktiv bog&#39;lanish (Link)&quot;">​</a></h3><p><code>Home_books</code> sahifasidagi kitob kartasini bosganda yangi yaratilgan <code>Book_details</code> sahifasiga o&#39;tuvchi oddiy interaktiv hodisa (Click → Open Page) yarating.</p><p><strong>Yechim:</strong> Kartani tanlash → O&#39;ng tarafdagi <code>Interactions</code> panelida <code>Click or Tap</code> ni bosish → <code>Open Link</code> → <code>Book_details</code> sahifasini tanlash.</p><h3 id="_3-topshiriq-wireframeni-png-ga-eksport-qilish" tabindex="-1">3-topshiriq. Wireframeni PNG ga eksport qilish <a class="header-anchor" href="#_3-topshiriq-wireframeni-png-ga-eksport-qilish" aria-label="Permalink to &quot;3-topshiriq. Wireframeni PNG ga eksport qilish&quot;">​</a></h3><p>Yaratilgan wireframeni kompyuterga <code>home_books_wireframe.png</code> nomi bilan saqlang.</p><p><strong>Yechim:</strong> Menyudan <code>Publish → Export Pages to Images</code> orqali saqlangan toza tasvir fayli.</p><hr>',12))]),i("div",q,[i("h2",y,[l(t,{name:"file-text"}),a[9]||(a[9]=r(" 4. Tezkor nazorat (5 daqiqa) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-5-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat (5 daqiqa)"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Axure RP dasturi nima uchun kerak va uning Balsamiqdan ustunligi nimada? <ul><li><strong>Javob:</strong> Axure RP geometrik toza wireframelar va murakkab mantiqiy interaktiv prototiplar yaratish imkonini beradi.</li></ul></li><li>Sahifalarni <code>Home_books</code> kabi tartibli nomlash nima uchun muhim? <ul><li><strong>Javob:</strong> Loyihada navigatsiyani osonlashtirish va jamoa a&#39;zolari bir-birini tushunishi uchun.</li></ul></li><li>Kulranglar ierarxiyasi (Grayscale) nima maqsadda qo&#39;llaniladi? <ul><li><strong>Javob:</strong> Ranglarsiz ham qaysi blok va matn muhimroq ekanini vizual ko&#39;rsatish uchun.</li></ul></li><li>Wireframe&#39;da Rectangle (To&#39;rtburchak) vositasi qanday vazifalarni bajaradi? <ul><li><strong>Javob:</strong> Bannerlar, kartalar, tugmalar va fon bloklarining asosiy qurilish g&#39;ishti sifatida.</li></ul></li><li>Yaratilgan wireframe keyingi bosqichda Figmaga qanday ko&#39;chiriladi? <ul><li><strong>Javob:</strong> PNG yoki SVG sifatida eksport qilinib, Figmaga fon rasmi (reference) qilib yuklanadi.</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",c,[l(t,{name:"file-text"}),a[12]||(a[12]=r(" 5. Xulosa va keyingi darsga ko'prik ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-xulosa-va-keyingi-darsga-ko-prik","aria-label":`Permalink to "<Icon name="file-text" /> 5. Xulosa va keyingi darsga ko'prik"`},"​",-1))]),a[14]||(a[14]=i("p",null,[r("2-hafta davomida biz foydalanuvchi ssenariylaridan boshlab, User Flow va Balsamiq/Axure RP vositalarida to'liq interfeys wireframe'ini yaratishni o'rgandik! "),i("strong",null,"Keyingi hafta (3-hafta, 7–9 darslar):"),r(" Axure RP va Balsamiqda wireframe yaratish amaliyotini davom ettiramiz, murakkab komponentlar va interaktiv prototiplash sirlarini chuqur o'rganamiz!")],-1))])])}const B=s(h,[["render",v]]);export{R as __pageData,B as default};
